    txt=Path(d['doc_path']).read_text(encoding='utf-8', errors='ignore')
    span=extract(txt)
    c=clean(span or '')
    gt=d['ground_truth'].lower()
    ok=False
    if '10-k' in gt and 'form 10 k' in c:
        ok=True
        if 'annual report' in gt:
            ok = 'annual report' in c
    elif '10-q' in gt and 'form 10 q' in c:
        ok=True
    elif '8-k current report' in gt:
        ok='form 8 k' in c and 'current report' in c
    elif '8-k' in gt:
        ok='form 8 k' in c
    elif 'earnings release' in gt:
        ok='news release' in c or 'press release' in c or 'earnings release' in c
    if not ok:
        miss.append((d['doc_name'], d['ground_truth'], span))
print('misses', len(miss))
for m in miss[:20]:
    print('\\n', m[0], m[1], '\\n', m[2])
