obj=json.loads(p.read_text())

FORM_PATTERNS=[
    re.compile(r'\\bform\\s*10\\s*[- ]?\\s*k\\b', re.I),
    re.compile(r'\\bform\\s*10\\s*[- ]?\\s*q\\b', re.I),
    re.compile(r'\\bform\\s*8\\s*[- ]?\\s*k\\b', re.I),
]

def norm(s):
    s=(s or '').replace('\\xa0',' ')
    s=re.sub(r'\\s+',' ',s).strip()
    return s

def clean(s):
    s=norm(s).lower()
    s=re.sub(r'["'^a-z0-9]+'"',' ',s)
    return ' '.join(s.split())

def extract(txt):
    lines=[norm(x) for x in txt.splitlines()]
    nonempty=[x for x in lines[:120] if x]
    c=' '.join(clean(x) for x in nonempty[:20])
    if ('news release' in c or 'press release' in c) and (
        'financial results' in c or 'earnings release' in c or re.search(r'reports (first|second|third|fourth) quarter', c)
    ):
        chosen=[]
        for line in nonempty[:8]:
            chosen.append(line)
            if len(chosen)>=5 and len(' '.join(chosen))>80:
                break
        return ' | '.join(chosen)
    for i,line in enumerate(lines[:120]):
        if not line:
            continue
        if any(p.search(line) for p in FORM_PATTERNS):
            chosen=[line]
            for nxt in lines[i+1:i+8]:
                n=norm(nxt)
                if not n:
                    continue
                chosen.append(n)
                joined=' '.join(clean(x) for x in chosen)
                if ('annual report' in joined or 'quarterly report' in joined or 'current report' in joined) and len(chosen)>=2:
                    break
                if len(chosen)>=4:
                    break
            return ' | '.join(chosen)
    return None

miss=[]
for d in obj['documents']:
    txt=Path(d['doc_path']).read_text(encoding='utf-8', errors='ignore')
    span=extract(txt)
    c=clean(span or '')
    gt=d['ground_truth'].lower()
